            const loc = start.sourceLocation();
            const declarations = (switch (css.DeclarationBlock.parse(input, parser.options)) {
.result => |vv| vv,
.err => |e| {
return .{ .err = e };
},
});
            _ = (blk_catch_1: { break :blk_catch_1 ((parser.rules.append(input.allocator(), PageMarginRule{ .margin_box = prelude, .declarations = declarations, .loc = Location{ .source_index = parser.options.source_index, .line = loc.line, .column = loc.column } })) catch |e| { _ = &e; break :blk_catch_1 bun.handleOom(e); }); });
            return .success;
    }

pub fn ruleWithoutBlock(_: *PageRuleParser, _: Prelude, _: *const css.ParserState) css.Maybe(AtRule,void) {
            return .{ .err = .{} };
    }
    pub const Prelude = PageMarginBox;
    pub const AtRule = void;
};

